const RouterTracer = ({ children }: { children: React.ReactNode }) => {
  const loc = useLocation()
  const renders = useRef(0)
  // useLayoutEffect to catch synchronous render updates before paint
  useLayoutEffect(() => {
    renders.current += 1
    try {
      console.log('[ROUTER-TRACER] layout', Date.now(), 'render=', renders.current, 'loc=', JSON.stringify(loc), 'hash=', window.location.hash)
    } catch (e) { /* ignore */ }
  }, [loc])
  // effect for async observation
  useEffect(() => {
    try { console.log('[ROUTER-TRACER] effect', Date.now(), 'loc=', JSON.stringify(loc), 'hash=', window.location.hash) } catch (e) { /* ignore */ }
  }, [loc])
  return <>{children}</>
}

export default function App() {
  // Keyed on the route so a crashed tab clears itself once you navigate away,
  // and so one bad page can never blank the sidebar / the whole window again.
  const { pathname } = useLocation()
  const navigate = useNavigate()
  // Expose a navigation shim to E2E diagnostics so the harness can drive navigation
  useEffect(() => {
    try {
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      // @ts-ignore - diagnostic global
      window.__npz_navTo = (p: string) => navigate(p)
      console.log('[APP-TRACE] __npz_navTo shim installed')
    } catch (e) { /* ignore */ }
    // Also listen for a custom test-only event that forces the router to re-run navigation
    const onForce = () => {
      try {
        const target = window.location.hash.startsWith('#') ? window.location.hash.slice(1) : window.location.hash
        console.log('[APP-TRACE] npz-force-nav received, navigating to', target)
        navigate(target || '/')
      } catch (err) { console.log('[APP-TRACE] npz-force-nav handler error', err) }
    }
    window.addEventListener('npz-force-nav', onForce)
    return () => {
      try {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        delete window.__npz_navTo
      } catch (e) { /* ignore */ }
      window.removeEventListener('npz-force-nav', onForce)
    }
  }, [navigate])

  // Diagnostic trace: log router-visible pathname changes during E2E investigations
  useEffect(() => {
    try { console.log('[APP-TRACE] pathname=', pathname, 'hash=', window.location.hash) } catch (e) { /* ignore */ }
  }, [pathname])

  // Also trace raw hashchange events directly to see whether the browser fires them
  useEffect(() => {
    const onHash = () => {
      try { console.log('[HASHCHANGE-EVENT] window.location.hash=', window.location.hash, 'location.pathname=', location.pathname) } catch (e) { /* ignore */ }
      try {
        // Test-only diagnostic: if enabled, force the router to navigate from the raw hash
        // This is guarded by window.__npz_diag_force_hash_nav so normal behavior is unchanged.
        // The harness can set that flag when reproducing the sequence.
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        if (window.__npz_diag_force_hash_nav) {
          const target = window.location.hash.startsWith('#') ? window.location.hash.slice(1) : window.location.hash
          try { console.log('[APP-TRACE] __npz_diag_force_hash_nav navigating to', target) } catch (e) { /* ignore */ }
          navigate(target || '/')
        }
      } catch (e) { /* ignore */ }
    }
    window.addEventListener('hashchange', onHash)
    return () => window.removeEventListener('hashchange', onHash)
  }, [navigate])

  // Periodic debug snapshot (short-lived): log pathname+hash pairs for 6s after mount
  useEffect(() => {
    let ticks = 0
    const id = setInterval(() => {
      try {
        ticks += 1
        console.log('[APP-POLL] t=', Date.now(), 'tick=', ticks, 'pathname=', pathname, 'hash=', window.location.hash)
        if (ticks >= 30) clearInterval(id)
      } catch (e) { /* ignore */ }
    }, 200)
    return () => clearInterval(id)
  }, [])

  return (
    <StudioProvider>
      <div className="flex h-screen w-screen overflow-hidden">
        <Sidebar />
        <main className="flex-1 overflow-y-auto">
          <ErrorBoundary label={pathname.replace('/', '') || 'Today'} resetKey={pathname}>
            <RouterTracer>
            <Routes>
              <Route path="/" element={<TodayPage />} />
              <Route path="/ideas" element={<IdeasPage />} />
              <Route path="/channel" element={<ChannelPage />} />
              <Route path="/agent" element={<AgentPage />} />
              <Route path="/scenes" element={<SceneStudioPage />} />
              <Route path="/writer" element={<WriterPage />} />
              <Route path="/scriptpad" element={<ScriptPadPage />} />
              <Route path="/video" element={<VideoPage />} />
              <Route path="/storyboard" element={<StoryboardPage />} />
              <Route path="/presenter" element={<PresenterPage />} />
              <Route path="/recorder" element={<RecorderPage />} />
              <Route path="/teleprompter" element={<TeleprompterPage />} />
              <Route path="/timeline" element={<TimelinePage />} />
              <Route path="/charts" element={<ChartsPage />} />
              <Route path="/psx" element={<PsxPage />} />
              <Route path="/nccpl" element={<NccplPage />} />
              <Route path="/advisor" element={<AdvisorPage />} />
              <Route path="/library" element={<LibraryPage />} />
              <Route path="/activity" element={<ActivityLogPage />} />
              <Route path="/settings" element={<SettingsPage />} />
            </Routes>
            </RouterTracer>
          </ErrorBoundary>
        </main>
        <FallbackBanner />
        <UpdateBanner />
        <OnboardingTour />
        <AssistantWidget />
        <GuideWidget />
        <CommandPalette />
        <ToastHost />
        <ConfirmHost />
      </div>
    </StudioProvider>
  )
}

/**
 * Settings → Caretaker: the scheduled self-diagnostic, made visible and his to command.
 *
 * Everything he asked for lives on this one card: is it working, what has it done up to
 * today, what its schedule is, the recommended schedule AND the reason for it (stated,
 * not implied), the power to change the schedule or pause it, and the power to delete
 * the record. What it fixes by itself is settings, state and stuck services — the card
 * never claims more than that.
 */
import { useEffect, useState } from 'react'
import type { CaretakerStatus } from '../../../shared/caretaker'
import { confirmDialog } from './Confirm'
import { toast } from './Toast'

function when(iso: string | null): string {
  if (!iso) return '—'
  const d = new Date(iso)
  return Number.isNaN(d.getTime()) ? '—' : d.toLocaleString()
}

export default function CaretakerCard(): React.JSX.Element {
  const [status, setStatus] = useState<CaretakerStatus | null>(null)
  const [hours, setHours] = useState(6)
  const [running, setRunning] = useState(false)
  const [showAll, setShowAll] = useState(false)

  async function refresh(): Promise<void> {
    try {
      const s = await window.api.caretaker.status()
      setStatus(s)
      setHours(s.intervalHours)
    } catch {
      setStatus(null)
    }
  }

  useEffect(() => {
    void refresh()
  }, [])

  async function runNow(): Promise<void> {
    setRunning(true)
    try {
      const run = await window.api.caretaker.runNow()
      toast(
        run.outcome === 'busy'
          ? 'A render is in progress — the Caretaker stood down rather than risk it.'
          : run.problems.length || run.fixed.length
            ? `Caretaker: ${run.problems.length} problem(s), ${run.fixed.length} fixed.`
            : 'Caretaker: everything healthy.',
        run.problems.length ? 'error' : 'success'
      )
      await refresh()
    } finally {
      setRunning(false)
    }
  }

  async function saveSchedule(paused: boolean): Promise<void> {
    setStatus(await window.api.caretaker.setSchedule(hours, paused))
    toast(paused ? 'Caretaker paused — nothing will run until you resume it.' : `Caretaker will check every ${hours} hour(s).`, 'info')
  }

  async function clearLog(): Promise<void> {
    const yes = await confirmDialog({
      title: "Delete the Caretaker's record?",
      message: 'The list of past check-ups is removed. The Caretaker itself keeps running on its schedule.',
      confirmLabel: 'Delete the record',
      danger: true
    })
    if (!yes) return
    setStatus(await window.api.caretaker.clearLog())
  }

  if (!status) return <></>

  const latest = status.runs[0]
  const shown = showAll ? status.runs.slice(0, 20) : status.runs.slice(0, 3)

  return (
    <div className="mt-4 rounded-lg border border-ink-700 bg-ink-900 p-4 space-y-3">
      <div className="flex items-center justify-between gap-3">
        <div>
          <div className="text-sm text-ink-100 font-medium">🩺 Caretaker — the studio checks itself</div>
          <p className="text-xs text-ink-500 mt-0.5">
            Runs the live health checks, moves the AI brain off a dead service, and looks for finished videos the
            app lost track of. It fixes settings and services; it never touches your work, and it never runs during a
            render.
          </p>
        </div>
        <span className={`shrink-0 text-xs ${status.paused ? 'text-amber-400' : 'text-emerald-400'}`}>
          {status.paused ? 'Paused' : 'Running'}
        </span>
      </div>

      <div className="rounded-md border border-ink-800 bg-ink-950 p-3 text-[11px] text-ink-400 space-y-1">
        <div>
          <span className="text-ink-500">Last check-up: </span>
          {latest ? `${when(latest.at)} — ${latest.outcome === 'busy' ? 'stood down (render in progress)' : latest.problems.length ? `${latest.problems.length} problem(s) found` : 'everything healthy'}${latest.fixed.length ? `, ${latest.fixed.length} fixed` : ''}` : 'not yet — the first one runs shortly after the app starts'}
        </div>
        <div>
          <span className="text-ink-500">Next scheduled: </span>
          {status.paused ? 'paused' : when(status.nextRunAt)}
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-2 text-xs">
        <label className="flex items-center gap-1 text-ink-400">
          Check every
          <input
            type="number"
            min={1}
            max={168}
            value={hours}
            onChange={(e) => setHours(Math.max(1, Math.min(168, Number(e.target.value) || 6)))}
            className="w-14 rounded bg-ink-800 border border-ink-700 px-2 py-1 text-ink-100"
          />
          hour(s)
        </label>
        <button onClick={() => void saveSchedule(false)} className="rounded-md bg-gold-500 hover:bg-gold-400 text-ink-950 font-medium px-3 py-1.5 transition-colors">
          Save schedule
        </button>
        <button
          onClick={() => void saveSchedule(!status.paused)}
          className="rounded-md border border-ink-700 hover:border-ink-600 text-ink-300 px-3 py-1.5 transition-colors"
        >
          {status.paused ? 'Resume' : 'Pause'}
        </button>
        <button onClick={() => void runNow()} disabled={running} className="rounded-md border border-ink-700 hover:border-ink-600 disabled:opacity-50 text-ink-300 px-3 py-1.5 transition-colors">
          {running ? 'Checking…' : 'Run a check-up now'}
        </button>
      </div>

      <p className="text-[11px] text-ink-600">
        Recommended: every {status.recommendedHours} hours. Why — {status.recommendedWhy}
      </p>

      {status.runs.length > 0 && (
        <div className="space-y-1.5">
          <div className="flex items-center justify-between">
            <span className="text-xs text-ink-300 font-medium">What it has done</span>
            <div className="flex gap-2">
              {status.runs.length > 3 && (
                <button onClick={() => setShowAll((v) => !v)} className="text-[11px] text-ink-500 hover:text-ink-300">
                  {showAll ? 'Show less' : `Show more (${status.runs.length})`}
                </button>
              )}
              <button onClick={() => void clearLog()} className="text-[11px] text-ink-500 hover:text-red-300">
                Delete the record
              </button>
            </div>
          </div>
          {shown.map((r) => (
            <div key={r.at} className="rounded-md border border-ink-800 bg-ink-950 p-2 text-[11px]">
              <div className="text-ink-400">
                {when(r.at)} · {r.trigger === 'manual' ? 'you ran it' : r.trigger === 'start' ? 'app start' : 'scheduled'} ·{' '}
                {r.outcome === 'busy' ? (
                  <span className="text-amber-300">stood down — render in progress</span>
                ) : r.problems.length ? (
                  <span className="text-red-300">{r.problems.join(', ')} failing</span>
                ) : (
                  <span className="text-emerald-400">all healthy</span>
                )}
              </div>
              {r.fixed.map((f) => (
                <div key={f} className="text-emerald-300 mt-0.5">✓ {f}</div>
              ))}
              {r.notes.map((n) => (
                <div key={n} className="text-ink-500 mt-0.5">ℹ {n}</div>
              ))}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'

interface Command {
  label: string
  hint: string
  run: () => void
}

/**
 * Command palette — press Ctrl-K (or Cmd-K) anywhere to jump to any tab or run a
 * common action by typing. Arrow keys to move, Enter to run, Esc to close. Makes the
 * whole app navigable in one keystroke.
 */
export default function CommandPalette(): React.JSX.Element | null {
  const navigate = useNavigate()
  const [open, setOpen] = useState(false)
  const [q, setQ] = useState('')
  const [sel, setSel] = useState(0)
  const inputRef = useRef<HTMLInputElement | null>(null)

  const commands = useMemo<Command[]>(() => {
    const go = (path: string): (() => void) => () => {
      navigate(path)
      setOpen(false)
    }
    return [
      { label: 'AI Command', hint: 'tell the studio what to do', run: go('/agent') },
      { label: 'Scene Studio', hint: 'build scene-by-scene', run: go('/scenes') },
      { label: 'Video Studio', hint: 'build / edit / publish videos', run: go('/video') },
      { label: 'Script Writer', hint: 'generate a script', run: go('/writer') },
      { label: 'Script Pad', hint: 'write your own', run: go('/scriptpad') },
      { label: 'Today', hint: 'home: latest videos & activity', run: go('/') },
      { label: 'Ideas & Trends', hint: 'brainstorm ideas', run: go('/ideas') },
      { label: 'Charts', hint: 'price charts', run: go('/charts') },
      { label: 'Advisor', hint: 'chat about your work', run: go('/advisor') },
      { label: 'Library', hint: 'saved ideas & scripts', run: go('/library') },
      { label: 'Activity Log', hint: 'history', run: go('/activity') },
      { label: 'Settings', hint: 'AI, voice, keys, health', run: go('/settings') }
    ]
  }, [navigate])

  const filtered = useMemo(() => {
    const s = q.trim().toLowerCase()
    if (!s) return commands
    return commands.filter((c) => (c.label + ' ' + c.hint).toLowerCase().includes(s))
  }, [q, commands])

  // Global Ctrl-K / Cmd-K toggle.
  useEffect(() => {
    const onKey = (e: KeyboardEvent): void => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault()
        setOpen((v) => !v)
        setQ('')
        setSel(0)
      } else if (e.key === 'Escape') {
        setOpen(false)
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  useEffect(() => {
    if (open) setTimeout(() => inputRef.current?.focus(), 30)
  }, [open])

  useEffect(() => {
    if (sel >= filtered.length) setSel(0)
  }, [filtered, sel])

  if (!open) return null

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/50 pt-28" onClick={() => setOpen(false)}>
      <div className="w-full max-w-lg rounded-lg border border-ink-700 bg-ink-900 shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <input
          ref={inputRef}
          value={q}
          onChange={(e) => setQ(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'ArrowDown') { e.preventDefault(); setSel((s) => Math.min(s + 1, filtered.length - 1)) }
            else if (e.key === 'ArrowUp') { e.preventDefault(); setSel((s) => Math.max(s - 1, 0)) }
            else if (e.key === 'Enter') { e.preventDefault(); filtered[sel]?.run() }
          }}
          placeholder="Jump to… (type a tab or action)"
          className="w-full rounded-t-lg bg-ink-950 border-b border-ink-800 px-4 py-3 text-sm text-ink-100 outline-none"
        />
        <div className="max-h-80 overflow-y-auto py-1">
          {filtered.length === 0 && <div className="px-4 py-3 text-xs text-ink-500">No matches.</div>}
          {filtered.map((c, i) => (
            <button
              key={c.label}
              onMouseEnter={() => setSel(i)}
              onClick={() => c.run()}
              className={`flex w-full items-center justify-between px-4 py-2 text-left text-sm ${i === sel ? 'bg-ink-800 text-gold-300' : 'text-ink-200'}`}
            >
              <span>{c.label}</span>
              <span className="text-[11px] text-ink-500">{c.hint}</span>
            </button>
          ))}
        </div>
        <div className="border-t border-ink-800 px-4 py-1.5 text-[10px] text-ink-600">↑↓ move · Enter open · Esc close · Ctrl-K toggles</div>
      </div>
    </div>
  )
}

/**
 * Five different openings for the script already written, built only from its own
 * sentences.
 *
 * The first fifteen seconds decide whether the other twelve minutes get watched, and they
 * are the hardest part to judge from inside the script. Seeing the same material as a
 * contradiction, as a number, as a question, as what is at stake, and as a mid-scene
 * opening makes the choice obvious in a way staring at the draft never does.
 *
 * Nothing is invented — every option is a sentence from the script, and the sentence it
 * came from is shown, so the writer can check it rather than trust it.
 */
import { useEffect, useState } from 'react'
import { rebuildHooks, summarise, type HookCandidate, type HookForm } from '../../../shared/hookRebuild'

const FORM_LABEL: Record<HookForm, string> = {
  contradiction: 'Contradiction',
  number: 'A number',
  question: 'A question',
  stake: "What's at stake",
  'in-media-res': 'Straight into it'
}

export default function HookRebuildPanel({
  script,
  onUse
}: {
  script: string
  /** Called with the chosen opening, so the writer can drop it into the draft. */
  onUse?: (text: string) => void
}): React.JSX.Element | null {
  const [open, setOpen] = useState(false)
  const [candidates, setCandidates] = useState<HookCandidate[]>([])
  const [copied, setCopied] = useState<string | null>(null)

  // Pure and instant — no AI, no network. Recomputed as the draft changes.
  useEffect(() => {
    setCandidates(open ? rebuildHooks(script) : [])
  }, [script, open])

  if (!script.trim()) return null

  return (
    <div className="rounded-lg border border-ink-700 bg-ink-900 p-4">
      <div className="flex items-center justify-between">
        <div className="text-sm text-ink-100 font-medium">Rebuild the first fifteen seconds</div>
        <button
          onClick={() => setOpen((o) => !o)}
          className="rounded-md bg-gold-500 hover:bg-gold-400 text-ink-950 text-xs font-medium px-3 py-1.5 transition-colors"
          title="Five different openings, built only from sentences already in your script — nothing invented"
        >
          {open ? 'Hide' : '✎ Show 5 openings'}
        </button>
      </div>

      {open && (
        <>
          <p className="text-xs text-ink-400 mt-2">{summarise(candidates)}</p>
          <div className="mt-3 space-y-2">
            {candidates.map((c) => (
              <div key={c.form} className="rounded-md border border-ink-800 bg-ink-950 p-3">
                <div className="flex items-center gap-2 mb-1.5">
                  <span className="text-[11px] text-gold-500 font-medium">{FORM_LABEL[c.form]}</span>
                  <span className="text-[11px] text-ink-500">{c.seconds}s spoken</span>
                </div>
                <div className="text-xs text-ink-100 leading-relaxed">{c.text}</div>
                <div className="text-[11px] text-ink-500 mt-1.5">{c.rationale}</div>
                {/* The sentence it came from, so this can be CHECKED rather than trusted. */}
                {c.sourceSentence !== c.text && (
                  <div className="text-[11px] text-ink-600 mt-1 italic">from: “{c.sourceSentence}”</div>
                )}
                <div className="flex gap-2 mt-2">
                  {onUse && (
                    <button
                      onClick={() => onUse(c.text)}
                      className="rounded-md border border-gold-500/40 text-gold-400 hover:bg-gold-500/10 text-[11px] px-2 py-1 transition-colors"
                    >
                      Put it at the top
                    </button>
                  )}
                  <button
                    onClick={() => {
                      void navigator.clipboard.writeText(c.text)
                      setCopied(c.form)
                      setTimeout(() => setCopied(null), 1500)
                    }}
                    className="rounded-md border border-ink-700 text-ink-300 hover:bg-ink-800 text-[11px] px-2 py-1 transition-colors"
                  >
                    {copied === c.form ? 'Copied' : 'Copy'}
                  </button>
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import type { MusicSuggestion, MusicTrack } from '../../../shared/types'

/**
 * The in-place music picker: mood-matched suggestions the AI derived from the script,
 * one tap to preview, one tap to use. Deliberately a small inline panel rather than a
 * separate screen — choosing a backing track should not lose your place in the edit.
 */
export default function MusicPicker({
  scriptText,
  current,
  onChoose,
  onClose
}: {
  scriptText: string
  current: MusicTrack | null
  onChoose: (t: MusicTrack) => void
  onClose: () => void
}): React.JSX.Element {
  const [loading, setLoading] = useState(true)
  const [result, setResult] = useState<MusicSuggestion | null>(null)
  const [query, setQuery] = useState('')
  const [playingId, setPlayingId] = useState<string | null>(null)
  const audioRef = useRef<HTMLAudioElement | null>(null)

  // Set the moment the user runs their OWN mood search: a slow mount-time suggest()
  // resolving late must never overwrite the results the user searched for.
  const userSearchedRef = useRef(false)

  useEffect(() => {
    let cancelled = false
    void window.api.music
      .suggest(scriptText)
      .then((r) => {
        if (!cancelled && !userSearchedRef.current) setResult(r)
      })
      .catch(() => {
        if (!cancelled && !userSearchedRef.current) setResult({ moods: [], tracks: [], note: 'Could not reach the free music services.' })
      })
      .finally(() => {
        if (!cancelled && !userSearchedRef.current) setLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [scriptText])

  // Stop any preview when the panel closes, so audio never keeps playing invisibly.
  useEffect(() => {
    return () => {
      audioRef.current?.pause()
    }
  }, [])

  async function runSearch(): Promise<void> {
    if (!query.trim()) return
    userSearchedRef.current = true
    setLoading(true)
    try {
      setResult(await window.api.music.moodSearch(query.trim()))
    } catch {
      setResult({ moods: [], tracks: [], note: 'Could not reach the free music services.' })
    } finally {
      setLoading(false)
    }
  }

  function preview(t: MusicTrack): void {
    if (playingId === t.id) {
      audioRef.current?.pause()
      setPlayingId(null)
      return
    }
    if (audioRef.current) {
      audioRef.current.pause()
      audioRef.current.src = t.url
      void audioRef.current.play().catch(() => setPlayingId(null))
      setPlayingId(t.id)
    }
  }

  return (
    <div className="mt-2 rounded-md border border-emerald-600/40 bg-ink-900 p-3 space-y-2">
      <div className="flex items-center justify-between">
        <span className="text-[11px] text-emerald-300 font-medium">♪ Choose background music — free &amp; copyright-safe</span>
        <button onClick={onClose} className="text-[11px] text-ink-500 hover:text-ink-200">
          Close
        </button>
      </div>

      {result?.moods.length ? (
        <div className="text-[10px] text-ink-500">
          Mood picked from your script: <span className="text-gold-300">{result.moods.join(', ')}</span>
          {result.synthMood ? (
            <span className="text-ink-600"> · the built-in music maker would play this as “{result.synthMood}”</span>
          ) : null}
        </div>
      ) : null}

      {result?.libraryLinks?.length ? (
        <div className="flex flex-wrap items-center gap-1.5 text-[10px] text-ink-500">
          Browse this vibe on the free libraries:
          {result.libraryLinks.map((l) => (
            <a
              key={l.url}
              href={l.url}
              target="_blank"
              rel="noreferrer"
              className="rounded border border-ink-700 px-1.5 py-0.5 text-ink-300 hover:border-gold-500 hover:text-gold-300"
            >
              {l.name} ↗
            </a>
          ))}
        </div>
      ) : null}

      <div className="flex gap-1.5">
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && void runSearch()}
          placeholder="Or search a mood: lo-fi, dramatic, hopeful…"
          className="flex-1 rounded-md bg-ink-800 border border-ink-700 px-2 py-1 text-xs text-ink-100 outline-none focus:border-gold-500"
        />
        <button
          onClick={() => void runSearch()}
          disabled={loading}
          className="rounded-md border border-ink-600 px-2 py-1 text-xs text-ink-300 hover:border-gold-500 disabled:opacity-40"
        >
          Search
        </button>
      </div>

      {loading && <div className="text-[11px] text-ink-400">Finding music…</div>}

      {!loading && result && result.tracks.length === 0 && (
        <div className="text-[11px] text-amber-300">
          {result.note || 'No free music found. Your video will simply be built without music.'}
        </div>
      )}

      <div className="space-y-1 max-h-56 overflow-y-auto">
        {result?.tracks.map((t) => (
          <div
            key={`${t.source}-${t.id}`}
            className={`flex items-center gap-2 rounded-md border p-2 ${
              current?.url === t.url ? 'border-emerald-500 bg-emerald-500/10' : 'border-ink-800 bg-ink-950'
            }`}
          >
            <button
              onClick={() => preview(t)}
              className="rounded-full border border-ink-600 w-7 h-7 text-xs text-ink-200 hover:border-gold-500 shrink-0"
              title="Preview"
            >
              {playingId === t.id ? '⏸' : '▶'}
            </button>
            <div className="min-w-0 flex-1">
              <div className="truncate text-xs text-ink-200">{t.title}</div>
              <div className="truncate text-[10px] text-ink-500">
                {t.tags}
                {t.durationSec ? ` · ${Math.round(t.durationSec)}s` : ''}
                <span className={t.needsAttribution ? ' text-amber-400' : ' text-emerald-400'}>
                  {t.needsAttribution ? ` · ${t.license} (credit needed)` : ` · ${t.license} (no credit needed)`}
                </span>
              </div>
            </div>
            <button
              onClick={() => onChoose(t)}
              className="shrink-0 rounded-md bg-gold-500 px-2.5 py-1 text-[11px] font-medium text-ink-950 hover:bg-gold-400"
            >
              {current?.url === t.url ? 'In use' : 'Use'}
            </button>
          </div>
        ))}
      </div>

      <audio ref={audioRef} onEnded={() => setPlayingId(null)} className="hidden" />
    </div>
  )
}

/**
 * Hear the script read out at speed, before you record it.
 *
 * The plan appears instantly — it is arithmetic, not audio — so the user sees what to
 * listen for and how long it will take before deciding to generate anything. Generating
 * the audio is the slow, optional second step.
 */
import { useEffect, useState } from 'react'
import { fileUrl } from '../../../shared/mediaUrl'
import { DEFAULT_SPEED, SPEED_CHOICES, formatDuration, type ProofKind, type ReadAloudPlan } from '../../../shared/readAloud'

const KIND_LABEL: Record<ProofKind, string> = {
  unsayable: 'Too long to say',
  breath: 'One breath',
  repeat: 'Said twice',
  number: 'Hard to say',
  tongue: 'Same sound',
  'mixed-language': 'Two languages'
}

const KIND_COLOUR: Record<ProofKind, string> = {
  unsayable: 'text-red-400',
  breath: 'text-amber-400',
  repeat: 'text-amber-400',
  number: 'text-amber-400',
  tongue: 'text-ink-400',
  'mixed-language': 'text-ink-400'
}

function clock(seconds: number): string {
  const t = Math.max(0, Math.round(seconds))
  return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`
}

export default function ReadAloudPanel({ script }: { script: string }): React.JSX.Element {
  const [speed, setSpeed] = useState<number>(DEFAULT_SPEED)
  const [plan, setPlan] = useState<ReadAloudPlan | null>(null)
  const [audioUrl, setAudioUrl] = useState<string | null>(null)
  const [engine, setEngine] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // The plan is instant, so it refreshes as the script and speed change — no button.
  useEffect(() => {
    let alive = true
    void window.api.readAloud
      .plan(script, speed)
      .then((p) => {
        if (alive) setPlan(p)
      })
      .catch(() => {
        /* an older build without the handler must not break the page */
      })
    return () => {
      alive = false
    }
  }, [script, speed])

  // A speed change invalidates the file that was made at the old speed.
  useEffect(() => {
    setAudioUrl(null)
  }, [speed])

  async function speak(): Promise<void> {
    setBusy(true)
    setError(null)
    try {
      const res = await window.api.readAloud.speak(script, speed, 'natural')
      if (res.ok) {
        // fileUrl() here, in the page — that is what makes this play on the phone too.
        setAudioUrl(`${fileUrl(res.path)}${fileUrl(res.path).includes('?') ? '&' : '?'}t=${Date.now()}`)
        setEngine(res.engineName)
        setPlan(res.plan)
      } else {
        setError(res.error)
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not read the script aloud.')
    } finally {
      setBusy(false)
    }
  }

  const hasScript = script.trim().length > 0

  return (
    <div className="rounded-lg border border-ink-700 bg-ink-900 p-4">
      <div className="flex items-center justify-between mb-2">
        <div className="text-sm text-ink-100 font-medium">Read it to me</div>
        <div className="flex items-center gap-2">
          <select
            value={speed}
            onChange={(e) => setSpeed(Number(e.target.value))}
            className="rounded-md bg-ink-950 border border-ink-700 text-ink-200 text-xs px-2 py-1.5"
            title="Double speed is the sweet spot: quick enough to actually do, slow enough that nothing is missed"
          >
            {SPEED_CHOICES.map((s) => (
              <option key={s} value={s}>
                {s}×{s === DEFAULT_SPEED ? ' (best)' : ''}
              </option>
            ))}
          </select>
          <button
            onClick={() => void speak()}
            disabled={busy || !hasScript}
            className="rounded-md bg-gold-500 hover:bg-gold-400 disabled:opacity-50 text-ink-950 text-xs font-medium px-3 py-1.5 transition-colors"
            title="Speaks the script with the offline voice, then speeds the recording up without making it squeaky"
          >
            {busy ? 'Speaking…' : '🔊 Read it aloud'}
          </button>
        </div>
      </div>

      <p className="text-xs text-ink-400">
        {plan?.headline ?? 'Write some script and this will tell you what to listen for.'}
      </p>

      {audioUrl && (
        <div className="mt-3">
          <audio src={audioUrl} controls autoPlay className="w-full h-9" />
          {engine && <div className="text-[11px] text-ink-600 mt-1">Spoken by {engine}.</div>}
        </div>
      )}

      {error && <div className="mt-2 text-xs text-red-300">{error}</div>}

      {plan && plan.notes.length > 0 && (
        <div className="mt-3 space-y-1.5">
          {plan.notes.map((n, i) => (
            <div key={`${n.sentence}-${n.kind}-${i}`} className="rounded-md border border-ink-800 bg-ink-950 p-2.5">
              <div className="flex items-center gap-2 mb-1">
                {/* The timestamp is in PLAYBACK time, so it matches the audio scrubber. */}
                <span className="text-[11px] text-ink-500 tabular-nums">{clock(n.atSecond / plan.speed)}</span>
                <span className={`text-[11px] font-medium ${KIND_COLOUR[n.kind]}`}>{KIND_LABEL[n.kind]}</span>
              </div>
              <div className="text-xs text-ink-300">{n.note}</div>
              <div className="text-[11px] text-ink-500 mt-1 italic">“{n.text}”</div>
            </div>
          ))}
        </div>
      )}

      {plan && plan.sentences.length > 0 && (
        <div className="mt-3 text-[11px] text-ink-600">
          {plan.sentences.length} sentences · {formatDuration(plan.scriptSeconds)} spoken at normal speed
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'

type Status = {
  state: 'current' | 'behind' | 'ahead' | 'unknown'
  runningTag: string
  publishedTag: string | null
  message: string
  checkedAt: string
}

/**
 * "Am I up to date?" — visible, on demand, with the evidence.
 *
 * WHY THIS EXISTS. The update banner only ever appeared when the app was BEHIND. When it
 * was current the app said nothing — and nothing is precisely what a broken check looks
 * like. Somebody who had just updated had no way to tell success from failure, and the
 * reasonable conclusion was "this is broken". That was not a documentation problem; the
 * app was missing a sentence. This is the sentence.
 *
 * It shows BOTH build stamps, not just a verdict, because a verdict on its own is another
 * thing to be taken on trust — and trust is exactly what runs out when an update is
 * invisible.
 */
export default function VersionCard(): React.JSX.Element {
  const [status, setStatus] = useState<Status | null>(null)
  // Starts true because the mount effect checks immediately — which is also the honest
  // label for that moment, and it keeps the effect from setting state synchronously.
  const [busy, setBusy] = useState(true)
  const [updating, setUpdating] = useState<string | null>(null)

  async function check(markBusy = true): Promise<void> {
    if (markBusy) setBusy(true)
    try {
      setStatus(await window.api.updates.status())
    } catch {
      setStatus(null)
    } finally {
      setBusy(false)
    }
  }

  useEffect(() => {
    void check(false)
  }, [])

  async function getUpdate(): Promise<void> {
    setUpdating('Working…')
    const off = window.api.updates.onInstallProgress(({ pct, stage }) =>
      setUpdating(pct > 0 && pct < 100 ? `${stage} ${pct}%` : stage)
    )
    try {
      const restarted = await window.api.updates.restart()
      if (restarted.ok) return
      const installed = await window.api.updates.install()
      setUpdating(
        installed.ok
          ? 'The installer is opening. Say yes to it and the app will reopen updated.'
          : (installed.error ?? 'Could not update.')
      )
      if (!installed.ok) await check()
    } finally {
      off()
    }
  }

  const tone =
    status?.state === 'current'
      ? 'border-emerald-800 bg-emerald-950/40 text-emerald-200'
      : status?.state === 'behind'
        ? 'border-sky-800 bg-sky-950/50 text-sky-100'
        : 'border-ink-700 bg-ink-900 text-ink-200'
  const icon = status?.state === 'current' ? '✓' : status?.state === 'behind' ? '⬆' : 'ⓘ'

  return (
    <div className={`mt-4 rounded-lg border p-4 ${tone}`}>
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <div className="text-sm font-medium">
            <span aria-hidden className="mr-1.5">
              {icon}
            </span>
            Version
          </div>
          <div className="text-xs mt-1">{busy ? 'Checking the download page…' : (status?.message ?? 'Not checked yet.')}</div>
          {updating && <div className="text-xs mt-1 opacity-90">{updating}</div>}
          {status && (
            // Both stamps, always. A bare verdict is one more thing to take on trust,
            // and trust is what runs out when an update is invisible.
            <div className="mt-2 space-y-0.5 text-[11px] opacity-70">
              <div>This app: {status.runningTag}</div>
              <div>Newest published: {status.publishedTag ?? 'could not be read'}</div>
              <div>Checked: {new Date(status.checkedAt).toLocaleTimeString()}</div>
            </div>
          )}
        </div>
        <div className="flex shrink-0 flex-col gap-1.5">
          <button
            onClick={() => void check()}
            disabled={busy}
            className="rounded bg-ink-700 hover:bg-ink-600 disabled:opacity-60 text-ink-100 text-[11px] font-medium px-2.5 py-1"
          >
            {busy ? 'Checking…' : 'Check now'}
          </button>
          {status?.state === 'behind' && (
            <button
              onClick={() => void getUpdate()}
              disabled={!!updating}
              className="rounded bg-sky-600 hover:bg-sky-500 disabled:opacity-60 text-white text-[11px] font-medium px-2.5 py-1"
            >
              Get the update
            </button>
          )}
        </div>
      </div>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'

export type SaveStatus = 'idle' | 'saving' | 'saved' | 'error'

/**
 * Universal autosave: restores a tab's saved state once on mount, then debounce-saves
 * it whenever it changes — so work is never lost on close/restart. Returns a status
 * for a "Saving…/Saved ✓" indicator. History (previous versions) is kept in the main
 * process; use loadHistory() to fetch it for a restore UI.
 */
export function useAutosave<T>(
  key: string,
  state: T,
  onRestore: (value: T) => void,
  options?: { skipRestore?: boolean }
): SaveStatus {
  const [status, setStatus] = useState<SaveStatus>('idle')
  const loaded = useRef(false)
  const restoreRef = useRef(onRestore)
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const latest = useRef(state)
  const dirty = useRef(false)
  restoreRef.current = onRestore
  latest.current = state
  const skipRestore = options?.skipRestore ?? false

  // Restore once — unless the caller is seeding fresh state (e.g. an imported document)
  // and must NOT be overwritten by the previously-saved draft.
  useEffect(() => {
    if (skipRestore) {
      loaded.current = true
      return
    }
    let cancelled = false
    void (async () => {
      try {
        const d = await window.api.drafts.get(key)
        if (!cancelled && d && d.current != null) restoreRef.current(d.current as T)
      } finally {
        if (!cancelled) loaded.current = true
      }
    })()
    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key])

  // Save (debounced) after the initial restore.
  useEffect(() => {
    if (!loaded.current) return
    setStatus('saving')
    dirty.current = true
    if (timer.current) clearTimeout(timer.current)
    timer.current = setTimeout(() => {
      window.api.drafts
        .set(key, latest.current)
        .then(() => {
          dirty.current = false
          setStatus('saved')
        })
        // A failed write used to pin the indicator on "Saving…" forever — the
        // user believed their work was safe when nothing had reached disk.
        .catch(() => setStatus('error'))
    }, 600)
    return () => {
      if (timer.current) clearTimeout(timer.current)
    }
     
  }, [key, state])

  // Flush any pending save on unmount (tab switch) and on app close, so the last <600ms
  // of edits are never lost — the docstring's promise the debounce alone can't keep.
  useEffect(() => {
    const flush = (): void => {
      if (loaded.current && dirty.current) void window.api.drafts.set(key, latest.current)
    }
    window.addEventListener('beforeunload', flush)
    return () => {
      window.removeEventListener('beforeunload', flush)
      flush()
    }
     
  }, [key])

  return status
}

/** Fetches the saved version history (newest first) for a key, for a restore dropdown. */
export async function loadHistory(key: string): Promise<{ at: string; value: unknown }[]> {
  const d = await window.api.drafts.get(key)
  return d?.history ?? []
}

import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * Undo/redo for structural editors (Timeline clips, Storyboard beats) — the places
 * where one wrong click used to be unrecoverable mid-session.
 *
 * Auto-records: every state change lands on the undo stack after a short debounce
 * (rapid slider drags collapse into one step), no call-site changes needed. Undo and
 * redo restore snapshots through the caller's own setter. Keyboard: Ctrl+Z / Ctrl+Y
 * (and Ctrl+Shift+Z), deliberately IGNORED while typing in an input/textarea — the
 * browser's native text undo owns those.
 */
export function useHistory<T>(
  state: T,
  restore: (value: T) => void
): { undo: () => void; redo: () => void; canUndo: boolean; canRedo: boolean } {
  const LIMIT = 60
  const DEBOUNCE_MS = 350
  const past = useRef<string[]>([])
  const future = useRef<string[]>([])
  const current = useRef<string>(JSON.stringify(state))
  const restoring = useRef(false)
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const restoreRef = useRef(restore)
  restoreRef.current = restore
  const [, bump] = useState(0)

  const serialized = JSON.stringify(state)

  useEffect(() => {
    if (serialized === current.current) return
    if (restoring.current) {
      // This change IS an undo/redo landing — record it as current, don't re-stack it.
      restoring.current = false
      current.current = serialized
      return
    }
    if (timer.current) clearTimeout(timer.current)
    const before = current.current
    current.current = serialized
    timer.current = setTimeout(() => {
      past.current.push(before)
      if (past.current.length > LIMIT) past.current.shift()
      future.current = [] // a fresh edit invalidates the redo branch
      bump((n) => n + 1)
    }, DEBOUNCE_MS)
    return () => {
      if (timer.current) clearTimeout(timer.current)
    }
  }, [serialized])

  const undo = useCallback((): void => {
    const prev = past.current.pop()
    if (prev === undefined) return
    future.current.push(current.current)
    restoring.current = true
    current.current = prev
    restoreRef.current(JSON.parse(prev) as T)
    bump((n) => n + 1)
  }, [])

  const redo = useCallback((): void => {
    const next = future.current.pop()
    if (next === undefined) return
    past.current.push(current.current)
    restoring.current = true
    current.current = next
    restoreRef.current(JSON.parse(next) as T)
    bump((n) => n + 1)
  }, [])

  useEffect(() => {
    const onKey = (e: KeyboardEvent): void => {
      const t = e.target as HTMLElement | null
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return
      if ((e.ctrlKey || e.metaKey) && !e.altKey && e.key.toLowerCase() === 'z') {
        e.preventDefault()
        if (e.shiftKey) redo()
        else undo()
      } else if ((e.ctrlKey || e.metaKey) && !e.altKey && e.key.toLowerCase() === 'y') {
        e.preventDefault()
        redo()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [undo, redo])

  return { undo, redo, canUndo: past.current.length > 0, canRedo: future.current.length > 0 }
}

import React from 'react'
import ReactDOM from 'react-dom/client'
import { unstable_HistoryRouter as HistoryRouter } from 'react-router-dom'
import { createHashHistory } from 'history'
import App from './App'
import './index.css'

// Diagnostic: instrument addEventListener/removeEventListener early so we can
// see which code registers hashchange/popstate handlers (helps identify if
// the router's listener is attached and from where). This runs before React mounts.
try {
  if (typeof window !== 'undefined' && !((window as any).__npz_listeners_hooked)) {
    const origAdd = window.addEventListener.bind(window)
    const origRemove = window.removeEventListener.bind(window)
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    window.addEventListener = function (ev, fn, ...args) {
      try {
        console.log('[WIN-ADD-EVENT-LISTENER] event=', ev, 'stack=', (new Error().stack || '').split('\n').slice(2,6).join(' | '))
      } catch (e) { /* ignore */ }
      return origAdd(ev, fn, ...args)
    }
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    window.removeEventListener = function (ev, fn, ...args) {
      try {
        console.log('[WIN-REMOVE-EVENT-LISTENER] event=', ev, 'stack=', (new Error().stack || '').split('\n').slice(2,6).join(' | '))
      } catch (e) { /* ignore */ }
      return origRemove(ev, fn, ...args)
    }
    // mark hooked so we don't double-wrap on HMR/dev
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    window.__npz_listeners_hooked = true
  }
} catch (err) {
  void err
}

// Create a hash history and log history events for debugging router internals.
const history = createHashHistory()
history.listen((loc, action) => {
  try { console.log('[HISTORY-LISTEN]', action, JSON.stringify(loc), Date.now(), (new Error().stack || '').split('\n').slice(2,8).join(' | ')) } catch (_) { void _ }
})


ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <HistoryRouter history={history}>
      <App />
    </HistoryRouter>
  </React.StrictMode>
)

import { useEffect, useRef, useState } from 'react'
import type { AgentPlan, AgentStep, AgentStepResult, VideoJob, VideoResolution, VideoStyle } from '../../../shared/types'
import { VIDEO_STYLES } from '../../../shared/types'
import MicButton, { appendDictation } from '../components/MicButton'
import BusyTimer from '../components/BusyTimer'
import { useAutosave } from '../hooks/useAutosave'
import { toast } from '../components/Toast'

import { fileUrl } from '../../../shared/mediaUrl'
import { releaseAgentRun, tryAcquireAgentRun } from '../store/agentRunLock'

const EXAMPLES = [
  'Write a 2-minute anime-style script about Pakistan\'s rupee and build it in 4K with calm music',
  'Build a cinematic video from my Script Pad at 1080p with sound effects',
  'Make a thumbnail that says MARKET MELTDOWN in a neon style',
  'Give me 5 video ideas about gold vs stocks, then write a short cartoon script on the best one and build it'
]

/** A short, human-readable one-liner describing a planned step. */
function describeStep(step: AgentStep): string {
  switch (step.type) {
    case 'write_script':
      return `📝 Write a script about "${step.topic}"${step.lengthMinutes ? ` (~${step.lengthMinutes} min)` : ''}`
    case 'build_video':
      return `🎬 Build a ${(step.resolution ?? '1080p').toUpperCase()} ${step.style ?? 'cinematic'} video (source: ${step.source}${step.aiVisuals ? ', AI visuals' : ''}${step.musicMood && step.musicMood !== 'none' ? `, ${step.musicMood} music` : ''}${step.soundEffects ? ', SFX' : ''})`
    case 'make_thumbnail':
      return `🖼 Make a ${step.style ?? 'cinematic'} thumbnail${step.aiBackground ? ' with AI background' : ''}: "${step.headline}"`
    case 'generate_image':
      return `🎨 Generate an image: "${step.prompt}"`
    case 'generate_ideas':
      return `💡 Generate ${step.count ?? 5} ideas about "${step.focus}"`
    case 'write_scriptpad':
      return `🗒 ${step.append ? 'Append to' : 'Write'} the Script Pad${step.title ? `: "${step.title}"` : ''}`
    case 'analyze_psx':
      return `📈 Analyze live PSX data for ${step.symbol}${step.makeScript ? ' + write a narration script' : ''}`
    case 'generate_music':
      return `🎵 Generate a ${step.seconds ?? 40}s ${step.mood} music bed`
    case 'plan_scenes':
      return `🎬 Plan the scene breakdown (from ${step.source ?? 'generated'} script)`
    default:
      return 'Unknown step'
  }
}

/**
 * AI Command Panel — the "just tell it what you want" tab. You type a request in plain
 * English; the active AI turns it into a plan of safe steps; you run it and watch the
 * studio write scripts, build videos, make thumbnails and generate ideas, live.
 */
export default function AgentPage(): React.JSX.Element {
  const [command, setCommand] = useState('')
  const saveStatus = useAutosave<string>('agent-command', command, (v) => setCommand(v))
  const [plan, setPlan] = useState<AgentPlan | null>(null)
  const [interpreting, setInterpreting] = useState(false)
  const [running, setRunning] = useState(false)
  const [log, setLog] = useState<string[]>([])
  const [preview, setPreview] = useState<string | null>(null)
  const [results, setResults] = useState<AgentStepResult[] | null>(null)
  const [error, setError] = useState<string | null>(null)
  const logEndRef = useRef<HTMLDivElement | null>(null)

  // Batch mode
  const [batchTopics, setBatchTopics] = useState('')
  const [batchStyle, setBatchStyle] = useState<VideoStyle>('cinematic')
  const [batchRes, setBatchRes] = useState<VideoResolution>('1080p')
  const [batchAi, setBatchAi] = useState(false)
  const [batchRunning, setBatchRunning] = useState(false)
  const [batchResults, setBatchResults] = useState<{ topic: string; ok: boolean; video?: VideoJob; error?: string }[] | null>(null)
  // "Overnight plan": same batch, but also cuts Shorts and drafts posting text per video —
  // pick topics before bed, wake up to publish-ready material instead of raw builds.
  const [overnight, setOvernight] = useState(false)
  const [shortsPerVideo, setShortsPerVideo] = useState(2)
  const [weeklyResults, setWeeklyResults] = useState<
    { topic: string; ok: boolean; videoId?: string; shorts: number; postingText?: string; error?: string }[] | null
  >(null)

  useEffect(() => {
    logEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [log])

  async function interpret(): Promise<void> {
    if (!command.trim() || interpreting || running) return
    setInterpreting(true)
    setError(null)
    setResults(null)
    setPlan(null)
    try {
      const p = await window.api.agent.interpret(command.trim())
      setPlan(p)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not interpret that command.')
    } finally {
      setInterpreting(false)
    }
  }

  async function run(): Promise<void> {
    if (!plan || !plan.steps.length || running) return
    // Same one-at-a-time lock the Producer/Expert widgets use: all three stream
    // over the SAME un-scoped agent:progress channel, so a widget run and a tab
    // run at once interleave stage lines into the wrong chat and race two builds.
    if (!tryAcquireAgentRun()) {
      toast('Another AI run is already in progress — wait for it to finish.', 'error')
      return
    }
    setRunning(true)
    setError(null)
    setResults(null)
    setLog([])
    setPreview(null)
    const unsubscribe = window.api.agent.onProgress((stage) => setLog((prev) => [...prev, stage]))
    // The opening-frame preview arrives on the shared video preview channel.
    const unsubPreview = window.api.video.onPreview((png) => setPreview(`${fileUrl(png)}?t=${Date.now()}`))
    try {
      const res = await window.api.agent.execute(plan)
      setResults(res.results)
      const ok = res.results.filter((r) => r.ok).length
      toast(`Done — ${ok}/${res.results.length} steps completed`, ok === res.results.length ? 'success' : 'info')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong while running the plan.')
      toast('The plan failed to run', 'error')
    } finally {
      unsubscribe()
      unsubPreview()
      releaseAgentRun()
      setRunning(false)
    }
  }

  async function runBatch(): Promise<void> {
    const topics = batchTopics.split('\n').map((t) => t.trim()).filter(Boolean)
    if (!topics.length || batchRunning) return
    if (!tryAcquireAgentRun()) {
      toast('Another AI run is already in progress — wait for it to finish.', 'error')
      return
    }
    setBatchRunning(true)
    setError(null)
    setBatchResults(null)
    setWeeklyResults(null)
    setLog([])
    const unsub = window.api.agent.onProgress((stage) => setLog((prev) => [...prev, stage]))
    try {
      if (overnight) {
        const res = await window.api.weekly.planRun(topics, {
          style: batchStyle,
          resolution: batchRes,
          aiVisuals: batchAi,
          shortsPerVideo
        })
        setWeeklyResults(res.report)
        const ok = res.report.filter((r) => r.ok).length
        const shorts = res.report.reduce((n, r) => n + r.shorts, 0)
        toast(`Overnight plan done — ${ok}/${res.report.length} videos, ${shorts} short(s)`, ok ? 'success' : 'error')
      } else {
        const res = await window.api.agent.batch(topics, batchStyle, batchRes, batchAi)
        setBatchResults(res.results)
        const ok = res.results.filter((r) => r.ok).length
        toast(`Batch done — ${ok}/${res.results.length} videos built`, ok ? 'success' : 'error')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Batch failed.')
      toast('Batch failed', 'error')
    } finally {
      unsub()
      releaseAgentRun()
      setBatchRunning(false)
    }
  }

  function copyPostingText(text: string): void {
    if (navigator.clipboard?.writeText) {
      void navigator.clipboard
        .writeText(text)
        .then(() => toast('Posting text copied ✓', 'success'))
        .catch(() => toast('Could not copy — select the text and press Ctrl+C', 'error'))
    } else {
      toast('Could not copy — select the text and press Ctrl+C', 'error')
    }
  }

  const busy = interpreting || running || batchRunning

  return (
    <div className="max-w-4xl mx-auto px-8 py-8">
      <header className="mb-6">
        <h1 className="text-2xl font-serif text-gold-400">AI Command</h1>
        <p className="text-ink-400 text-sm mt-1">
          Tell the studio what you want in plain English. It plans the work with your active AI brain
          (free Ollama or a paid key in Settings), then does it — writing scripts, building videos, making
          thumbnails and ideas — and shows every step as it happens.
        </p>
      </header>

      <div className="rounded-lg border border-ink-800 bg-ink-900 p-4">
        <textarea
          value={command}
          onChange={(e) => setCommand(e.target.value)}
          onKeyDown={(e) => {
            if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') void interpret()
          }}
          placeholder="e.g. Write a 90-second anime script about oil prices and build it in 4K with tense music, then make a thumbnail that says CRUDE SHOCK"
          rows={3}
          disabled={busy}
          className="w-full resize-y rounded-md bg-ink-950 border border-ink-800 px-3 py-2 text-sm text-ink-100 placeholder:text-ink-600 focus:border-gold-500 focus:outline-none"
        />
        <div className="mt-3 flex flex-wrap items-center gap-2">
          <button
            onClick={() => void interpret()}
            disabled={busy || !command.trim()}
            className="rounded-md bg-gold-500 px-4 py-2 text-sm font-medium text-ink-950 hover:bg-gold-400 disabled:opacity-40"
          >
            {interpreting ? 'Thinking…' : 'Plan it'}
          </button>
          {plan && plan.steps.length > 0 && (
            <button
              onClick={() => void run()}
              disabled={busy}
              className="rounded-md bg-emerald-600 px-4 py-2 text-sm font-medium text-white hover:bg-emerald-500 disabled:opacity-40"
            >
              {running ? 'Running…' : '▶ Run it'}
            </button>
          )}
          <MicButton onText={(t) => setCommand((prev) => appendDictation(prev, t))} className="px-3 py-1" />
          {interpreting && <BusyTimer label="Planning" />}
          <span className="text-[11px] text-ink-600">Ctrl+Enter to plan · 🎤 to speak</span>
          <span className="ml-auto text-[11px] text-ink-500">
            {saveStatus === 'saving' ? 'Saving…' : saveStatus === 'saved' ? 'Saved ✓' : saveStatus === 'error' ? '! not saved (disk error)' : ''}
          </span>
        </div>

        {!plan && !busy && (
          <div className="mt-4">
            <div className="text-[11px] uppercase tracking-wider text-ink-500 mb-2">Try one of these</div>
            <div className="flex flex-col gap-1.5">
              {EXAMPLES.map((ex) => (
                <button
                  key={ex}
                  onClick={() => setCommand(ex)}
                  className="text-left text-xs text-ink-400 hover:text-gold-400 rounded px-2 py-1 hover:bg-ink-800"
                >
                  “{ex}”
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {error && (
        <div className="mt-4 rounded-md border border-red-800 bg-red-950/40 px-4 py-3 text-sm text-red-300">{error}</div>
      )}

      {/* Batch mode */}
      <details className="mt-4 rounded-lg border border-ink-800 bg-ink-900">
        <summary className="cursor-pointer px-4 py-2 text-sm text-gold-400 select-none">📦 Batch — make many videos at once</summary>
        <div className="px-4 pb-4 pt-1 space-y-2">
          <textarea
            value={batchTopics}
            onChange={(e) => setBatchTopics(e.target.value)}
            placeholder={'One topic per line — e.g.\nGold vs stocks in 2026\nWhy the rupee is falling\nHow to start investing with 10,000'}
            rows={4}
            disabled={batchRunning}
            className="w-full resize-y rounded-md bg-ink-950 border border-ink-800 px-3 py-2 text-sm text-ink-100"
          />
          <div className="flex flex-wrap items-center gap-2 text-xs text-ink-300">
            <label className="flex items-center gap-1">
              Style
              <select value={batchStyle} onChange={(e) => setBatchStyle(e.target.value as VideoStyle)} className="rounded bg-ink-800 border border-ink-700 px-2 py-1 capitalize">
                {VIDEO_STYLES.map((s) => <option key={s} value={s} className="capitalize">{s}</option>)}
              </select>
            </label>
            <label className="flex items-center gap-1">
              Resolution
              <select value={batchRes} onChange={(e) => setBatchRes(e.target.value as VideoResolution)} className="rounded bg-ink-800 border border-ink-700 px-2 py-1">
                <option value="1080p">1080p</option>
                <option value="1440p">1440p</option>
                <option value="4k">4K</option>
              </select>
            </label>
            <label className="flex items-center gap-1 cursor-pointer">
              <input type="checkbox" checked={batchAi} onChange={(e) => setBatchAi(e.target.checked)} className="accent-gold-500" />
              Free AI visuals
            </label>
            <button
              onClick={() => void runBatch()}
              disabled={busy || !batchTopics.trim()}
              className="ml-auto rounded-md bg-gold-500 px-4 py-2 text-sm font-medium text-ink-950 hover:bg-gold-400 disabled:opacity-40"
            >
              {batchRunning ? (overnight ? 'Running overnight plan…' : 'Making videos…') : overnight ? '🌙 Run overnight plan' : '▶ Make all'}
            </button>
          </div>
          <div className="flex flex-wrap items-center gap-2 text-xs text-ink-300 rounded-md border border-gold-500/30 bg-ink-950/60 px-2 py-1.5">
            <label className="flex items-center gap-1.5 cursor-pointer">
              <input type="checkbox" checked={overnight} onChange={(e) => setOvernight(e.target.checked)} className="accent-gold-500" />
              <span className="text-gold-300">🌙 Overnight plan</span>
            </label>
            {overnight && (
              <label className="flex items-center gap-1">
                Shorts per video
                <select
                  value={shortsPerVideo}
                  onChange={(e) => setShortsPerVideo(Number(e.target.value))}
                  className="rounded bg-ink-800 border border-ink-700 px-2 py-1"
                >
                  {[0, 1, 2, 3, 4, 5].map((n) => <option key={n} value={n}>{n}</option>)}
                </select>
              </label>
            )}
            <span className="text-ink-500">
              Also cuts Shorts and writes posting text for each video — pick topics, walk away, come back to
              publish-ready material.
            </span>
          </div>
          <p className="text-[10px] text-ink-600">
            Writes a script and builds a video for each line (up to 25). Each is saved in Video Studio. One failure
