              {plan.steps.map((step, i) => (
                <li key={i} className="flex items-start gap-2 text-sm text-ink-300">
                  <span className="text-ink-600 tabular-nums">{i + 1}.</span>
                  <span>{describeStep(step)}</span>
                </li>
              ))}
