                <NumField label="In (s)" value={c.inSec} min={0} onChange={(v) => patchVideo(c.id, { inSec: Math.min(v, c.outSec) })} />
                <NumField label="Out (s)" value={c.outSec} min={0} onChange={(v) => patchVideo(c.id, { outSec: Math.max(v, c.inSec) })} />
