              <RepurposePanel title={writer.script.title} body={writer.body} />
              <p className="text-[11px] text-ink-500 mt-2">
                Want a narrated video of this script? Head to the <span className="text-gold-400">Video Studio</span>{' '}
                tab — this draft is available there.
              </p>
              {voiceoverStatus && <p className="text-xs text-ink-400 mt-2">{voiceoverStatus}</p>}
              {writer.thumbnailBrief && (
                <div className="mt-3 rounded-md border border-ink-700 bg-ink-800 p-3">
                  <div className="text-xs text-gold-400 font-medium mb-1">Thumbnail Brief (AI idea)</div>
                  <pre className="whitespace-pre-wrap font-sans text-xs text-ink-200 leading-relaxed">
                    {writer.thumbnailBrief}
                  </pre>
                </div>
              )}

              {/* Real, downloadable thumbnail IMAGE generator (free, offline). */}
              <div className="mt-3 rounded-md border border-ink-700 bg-ink-800 p-3 space-y-2">
                <div className="flex items-center justify-between">
                  <div className="text-xs text-gold-400 font-medium">Thumbnail Image (free, downloadable)</div>
                  <MicButton onText={(t) => setThumbHeadline((prev) => appendDictation(prev, t))} />
                </div>
                <input
                  value={thumbHeadline}
                  onChange={(e) => setThumbHeadline(e.target.value)}
                  placeholder={writer.script?.title || 'Punchy thumbnail headline'}
                  className="w-full rounded-md bg-ink-900 border border-ink-700 px-3 py-2 text-sm text-ink-100 outline-none focus:border-gold-500"
                />
                <div className="flex flex-wrap items-center gap-2">
                  <select
                    value={thumbStyle}
                    onChange={(e) => setThumbStyle(e.target.value as VideoStyle)}
                    className="rounded-md bg-ink-900 border border-ink-700 px-2 py-1.5 text-xs text-ink-100 outline-none focus:border-gold-500 capitalize"
                  >
                    {VIDEO_STYLES.map((s) => (
                      <option key={s} value={s} className="capitalize">
                        {s}
                      </option>
                    ))}
                  </select>
                  <button
                    onClick={handleRenderThumbnail}
                    disabled={renderingThumb}
                    className="rounded-md bg-gold-500 hover:bg-gold-400 disabled:opacity-50 text-ink-950 text-xs font-medium px-3 py-1.5 transition-colors"
                  >
                    {renderingThumb ? 'Rendering…' : '🖼 Generate image'}
                  </button>
                  {thumbImage && (
                    <button
                      onClick={handleSaveThumbnail}
                      className="rounded-md border border-ink-600 hover:border-ink-400 text-ink-200 text-xs px-3 py-1.5 transition-colors"
                    >
                      ⬇ Download PNG
                    </button>
                  )}
                </div>
                {thumbImage && (
                  <img src={thumbImage} alt="Generated thumbnail" className="w-full rounded-md border border-ink-700" />
                )}
                {thumbSaveNote && <p className="text-[11px] text-emerald-400 break-all">{thumbSaveNote}</p>}
                <p className="text-[10px] text-ink-600">
                  Leave the headline blank to use your title. This makes a real 1280×720 PNG (styled text on a themed
                  background) you can upload to YouTube — free and offline.
                </p>
              </div>
            </div>
          ) : (
            <div className="rounded-lg border border-dashed border-ink-700 h-full min-h-[420px] flex items-center justify-center text-ink-600 text-sm">
              Your generated script will appear here.
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

import { useEffect, useRef } from 'react'

/**
 * The Producer context bus. Any page that has an editable document (a script, a title,
 * a storyboard brief, notes) registers it here so the global "YouTube Producer" panel
 * can (a) ground its suggestions in what you're actually writing and (b) APPLY an edit
 * back into that field — but only when you click Apply. Mirrors the toast/confirm pattern.
 */
export type ProducerKind = 'script' | 'title' | 'brief' | 'notes'

export interface ProducerTarget {
  /** Human label shown in the panel, e.g. "Script Writer". */
  label: string
  kind: ProducerKind
  /** The current text of the field. */
  text: string
  /** Applies a revised version back into the field (only called on the user's Apply). */
  apply: (next: string) => void
}

let target: ProducerTarget | null = null
let listeners: (() => void)[] = []

export function registerProducerTarget(t: ProducerTarget | null): void {
  // Diagnostic logging for E2E investigation: which page registers as the Producer target
  try {
    if (t && typeof t.label === 'string') console.log('[PRODUCER] registerProducerTarget:', t.label, t.kind)
    else if (t === null) console.log('[PRODUCER] registerProducerTarget: null (cleared)')
  } catch (_) {}
  target = t
  try {
    // Invoke listeners asynchronously to avoid re-entrancy during routing/hashchange handling in E2E scenarios.
    console.log('[PRODUCER] scheduling listeners, count=', listeners.length)
    try { window.requestAnimationFrame(() => {
      try {
        console.log('[PRODUCER] invoking listeners (async), count=', listeners.length)
        listeners.forEach((l, i) => {
          try {
            try { console.log('[PRODUCER] invoking listener', i, 'at', Date.now()) } catch (_) {}
            l()
          } catch (err) {
            try { console.log('[PRODUCER] listener', i, 'threw', err && err.message ? err.message : String(err)) } catch (_) {}
          }
        })
      } catch (err) {
        try { console.log('[PRODUCER] failed invoking listeners (async)', err && err.message ? err.message : String(err)) } catch (_) {}
      }
    }) } catch (_) { queueMicrotask(() => {
      try {
        console.log('[PRODUCER] invoking listeners (async-fallback), count=', listeners.length)
        listeners.forEach((l, i) => {
          try {
            try { console.log('[PRODUCER] invoking listener (fallback)', i, 'at', Date.now()) } catch (_) {}
            l()
          } catch (err) {
            try { console.log('[PRODUCER] listener', i, 'threw', err && err.message ? err.message : String(err)) } catch (_) {}
          }
        })
      } catch (err) {
        try { console.log('[PRODUCER] failed invoking listeners (async-fallback)', err && err.message ? err.message : String(err)) } catch (_) {}
      }
    }) }
  } catch (err) {
    try { console.log('[PRODUCER] failed scheduling listeners', err && err.message ? err.message : String(err)) } catch (_) {}
  }
}
export function getProducerTarget(): ProducerTarget | null {
  return target
}
export function subscribeProducerTarget(cb: () => void): () => void {
  listeners.push(cb)
  return () => {
    listeners = listeners.filter((x) => x !== cb)
  }
}

/**
 * Register the current page's editable target with the Producer. Registers a STABLE proxy
 * that always reads the latest text/apply from a ref, and only re-registers when the
 * identity (label/kind) actually changes — so typing doesn't thrash the global bus or
 * re-render the Producer panel on every keystroke. Clears on unmount. Pass null to opt out.
 */
export function useProducerTarget(t: ProducerTarget | null): void {
  const ref = useRef(t)
  ref.current = t
  const label = t?.label
  const kind = t?.kind
  useEffect(() => {
    if (!ref.current) {
      registerProducerTarget(null)
      return
    }
    registerProducerTarget({
      get label() {
        return ref.current?.label ?? ''
      },
      get kind() {
        return ref.current?.kind ?? 'notes'
      },
      get text() {
        return ref.current?.text ?? ''
      },
      apply: (next: string) => ref.current?.apply(next)
    } as ProducerTarget)
    return () => registerProducerTarget(null)
     
  }, [label, kind])
}

import { createContext, useContext, useEffect, useRef, useState, type ReactNode } from 'react'
import type { GeneratedScript, LanguageMix, ScriptLength, ScriptStyle, VideoIdea } from '../../../shared/types'
import type { SaveStatus } from '../hooks/useAutosave'

/**
 * App-level state that must survive tab navigation. The provider lives above the
 * router in App, so switching pages does not unmount it — inputs and last results
 * persist. Nothing here is ever reset automatically: the only resets are the
 * explicit user-triggered clearIdeas()/clearWriter() functions, wired solely to
 * the per-tab "Clear" buttons.
 */

export interface IdeasState {
  focusArea: string
  audienceNote: string
  count: number
  ideas: VideoIdea[]
}

export interface WriterState {
  topic: string
  ideaContext: string
  audienceNote: string
  verifiedData: string
  length: ScriptLength
  languageMix: LanguageMix
  styles: ScriptStyle[]
  script: GeneratedScript | null
  body: string
  thumbnailBrief: string | null
}

const DEFAULT_IDEAS: IdeasState = {
  focusArea: 'Pakistan economy & personal finance',
  audienceNote: '',
  count: 5,
  ideas: []
}

const DEFAULT_WRITER: WriterState = {
  topic: '',
  ideaContext: '',
  audienceNote: '',
  verifiedData: '',
  length: 'long',
  languageMix: 'balanced',
  styles: ['standard'],
  script: null,
  body: '',
  thumbnailBrief: null
}

interface SceneState {
  title: string
  body: string
  // images or other scene metadata can be added later; keep minimal for compatibility
  images?: any[]
}

const DEFAULT_SCENE: SceneState = { title: '', body: '', images: [] }

interface StudioContextValue {
  ideas: IdeasState
  setIdeas: (patch: Partial<IdeasState> | ((prev: IdeasState) => Partial<IdeasState>)) => void
  clearIdeas: () => void
  writer: WriterState
  /**
   * Accepts a patch OR an updater reading the LATEST state. The updater form is
   * for async completions (dictation transcripts): a plain patch built from the
   * render-time value silently overwrote anything typed while the mic was busy.
   */
  setWriter: (patch: Partial<WriterState> | ((prev: WriterState) => Partial<WriterState>)) => void
  clearWriter: () => void
  /**
   * Shared scene state to allow Ideas → Writer → Scene Studio handoff. Kept
   * backwards-compatible: always present and never undefined so older pages
   * won't crash if they read it.
   */
  scene: SceneState
  setScene: (patch: Partial<SceneState> | ((prev: SceneState) => Partial<SceneState>)) => void
  /** Autosave status for a "Saving…/Saved ✓" indicator. */
  saveStatus: SaveStatus
}

const StudioContext = createContext<StudioContextValue | null>(null)
const DRAFT_KEY = 'studio'

export function StudioProvider({ children }: { children: ReactNode }) {
  const [ideas, setIdeasState] = useState<IdeasState>(DEFAULT_IDEAS)
  const [writer, setWriterState] = useState<WriterState>(DEFAULT_WRITER)
  const [scene, setSceneState] = useState<SceneState>(DEFAULT_SCENE)
  const [saveStatus, setSaveStatus] = useState<SaveStatus>('idle')
  const loaded = useRef(false)
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)

  // Restore the last session once on startup — so Ideas & Writer survive close/restart.
  useEffect(() => {
    void (async () => {
      try {
        const d = await window.api.drafts.get(DRAFT_KEY)
        const cur = d?.current as { ideas?: IdeasState; writer?: WriterState; scene?: SceneState } | undefined
        if (cur?.ideas) setIdeasState((p) => ({ ...p, ...cur.ideas }))
        if (cur?.writer) setWriterState((p) => ({ ...p, ...cur.writer }))
        if (cur?.scene) setSceneState((p) => ({ ...p, ...cur.scene }))
      } finally {
        loaded.current = true
      }
    })()
  }, [])

  // Autosave (debounced) whenever Ideas/Writer/Scene change.
  useEffect(() => {
    // Diagnostic guard: allow disabling autosave for targeted E2E debugging by
    // setting window.__npz_diag_disable_autosave = true in the page context.
    try {
      if ((window as any).__npz_diag_disable_autosave) return
    } catch (_) {}

    if (!loaded.current) return
    setSaveStatus('saving')
    if (timer.current) clearTimeout(timer.current)
    timer.current = setTimeout(() => {
      try {
        console.log('[STUDIO-AUTOSAVE] writing draft at', Date.now(), 'writer.topic=', String(writer.topic).slice(0,50))
      } catch (_) {}
      window.api.drafts
        .set(DRAFT_KEY, { ideas, writer, scene })
        .then(() => {
          try { console.log('[STUDIO-AUTOSAVE] write complete at', Date.now()) } catch (_) {}
          setSaveStatus('saved')
        })
        // A failed write must not sit on "Saving…" forever pretending to work.
        .catch((e) => {
          try { console.log('[STUDIO-AUTOSAVE] write failed', e && e.message ? e.message : String(e)) } catch (_) {}
          setSaveStatus('error')
        })
    }, 600)
    return () => {
      if (timer.current) clearTimeout(timer.current)
    }
  }, [ideas, writer, scene])

  const value: StudioContextValue = {
    ideas,
    setIdeas: (patch) => {
      try { console.log('[STUDIO] setIdeas deferred at', Date.now()) } catch (_) {}
      // Defer to the next animation frame to avoid synchronous re-entrancy during navigation/autosave tight windows
      try { window.requestAnimationFrame(() => {
        try {
          setIdeasState((prev) => ({ ...prev, ...(typeof patch === 'function' ? patch(prev) : patch) }))
        } catch (_) {}
      }) } catch (_) { queueMicrotask(() => {
        try { setIdeasState((prev) => ({ ...prev, ...(typeof patch === 'function' ? patch(prev) : patch) })) } catch (_) {}
      }) }
    },

    clearIdeas: () => setIdeasState(DEFAULT_IDEAS),
    writer,
    setWriter: (patch) => {
      try { console.log('[STUDIO] setWriter called — patch type:', typeof patch === 'function' ? 'fn' : 'object') } catch (_) {}
      // Defer the state update to avoid synchronous re-entrancy that can interfere with
      // routing in tight E2E sequences (diagnostic/backwards-compatible safety).
      try { window.requestAnimationFrame(() => {
        try {
          try { console.log('[STUDIO] setWriter deferred at', Date.now()) } catch (_) {}
          setWriterState((prev) => {
            const next = { ...prev, ...(typeof patch === 'function' ? patch(prev) : patch) }
            try { console.log('[STUDIO] setWriter result snapshot: topic=', String(next.topic).slice(0,80)) } catch (_) {}
            return next
          })
        } catch (_) {}
      }) } catch (_) { queueMicrotask(() => {
        try {
          setWriterState((prev) => {
            const next = { ...prev, ...(typeof patch === 'function' ? patch(prev) : patch) }
            try { console.log('[STUDIO] setWriter result snapshot: topic=', String(next.topic).slice(0,80)) } catch (_) {}
            return next
          })
        } catch (_) {}
      }) }
    },


    clearWriter: () => setWriterState(DEFAULT_WRITER),
    // scene is intentionally always present to avoid consumer crashes
    scene,
    setScene: (patch) => {
      try { console.log('[STUDIO] setScene deferred at', Date.now()) } catch (_) {}
      // Defer to the next animation frame to avoid synchronous re-entrancy during navigation/autosave tight windows
      try { window.requestAnimationFrame(() => {
        try { setSceneState((prev) => ({ ...prev, ...(typeof patch === 'function' ? patch(prev) : patch) })) } catch (_) {}
      }) } catch (_) { queueMicrotask(() => { try { setSceneState((prev) => ({ ...prev, ...(typeof patch === 'function' ? patch(prev) : patch) })) } catch (_) {} }) }
    },
    saveStatus
  }

  return <StudioContext.Provider value={value}>{children}</StudioContext.Provider>
}

export function useStudio(): StudioContextValue {
  const ctx = useContext(StudioContext)
  if (!ctx) throw new Error('useStudio must be used within StudioProvider')
  return ctx
}
